#!/usr/bin/env bash
set -euo pipefail
cd "$(dirname "$0")/.."
# VM exports carry only validated, portable settings generated by prepare.py.
if [[ -f .e2e-settings.env ]]; then source .e2e-settings.env; fi
command -v docker >/dev/null
docker compose version >/dev/null
if [[ $(docker info --format '{{.OSType}}') != linux ]]; then
  echo 'Compose mode requires a Linux Docker daemon.' >&2; exit 1
fi
# This mode uses Linux host networking for loopback-only tunnel origins.
if [[ $(uname -s) != Linux ]]; then
  echo 'Run Compose mode on a Linux host (for example a disposable GCP VM).' >&2; exit 1
fi
export COMPOSE_PROJECT_NAME="e2e-$(date +%s)-$$"
export E2E_RUN_ROOT="$(pwd)/artifacts/$COMPOSE_PROJECT_NAME"
export E2E_RUNTIME_IMAGE="${E2E_RUNTIME_IMAGE:-e2e-scope-runtime:local}"
export E2E_GETH_PORT="${E2E_GETH_PORT:-0}"
python3 docker/prepare.py "$E2E_RUN_ROOT"
compose=(docker compose -f "$E2E_RUN_ROOT/scope/docker/compose.yaml")
cleanup() {
  code=$?
  trap - EXIT INT TERM
  "${compose[@]}" logs --no-color >"$E2E_RUN_ROOT/artifacts/compose.log" 2>&1 || true
  docker image inspect "$E2E_RUNTIME_IMAGE" \
    "${E2E_GETH_IMAGE:-livepeer/geth-with-livepeer-protocol:confluence}" \
    "${E2E_CLOUDFLARED_IMAGE:-cloudflare/cloudflared:2026.9.1}" \
    >"$E2E_RUN_ROOT/artifacts/images.json" 2>/dev/null || true
  # Include dynamically launched fixtures and tunnels after an interrupted test.
  docker ps -aq --filter "label=com.docker.compose.project=$COMPOSE_PROJECT_NAME" | xargs -r docker rm -f >/dev/null 2>&1 || true
  "${compose[@]}" down --volumes --remove-orphans >/dev/null 2>&1 || true
  if docker image inspect "$E2E_RUNTIME_IMAGE" >/dev/null 2>&1; then
    # Tests run as container root. Remove private wallets even after a timeout,
    # and return retained results to the invoking host user for collection.
    docker run --rm -v "$E2E_RUN_ROOT:$E2E_RUN_ROOT" "$E2E_RUNTIME_IMAGE" \
      sh -c 'rm -rf "$1/tmp" "$1/container.env"; chown -R "$2:$3" "$1/artifacts"' \
      sh "$E2E_RUN_ROOT" "$(id -u)" "$(id -g)" || code=1
  else
    rm -rf "$E2E_RUN_ROOT/tmp" "$E2E_RUN_ROOT/container.env"
  fi
  echo "Compose artifacts: $E2E_RUN_ROOT/artifacts"
  exit "$code"
}
trap cleanup EXIT
trap 'exit 130' INT
trap 'exit 143' TERM
docker build -t "$E2E_RUNTIME_IMAGE" -f docker/Dockerfile docker
docker volume create e2e-scope-go-modules >/dev/null
docker volume create e2e-scope-go-build >/dev/null
"${compose[@]}" run --rm -T builder bash "$E2E_RUN_ROOT/scope/docker/build.sh"
"${compose[@]}" up -d geth
published=$("${compose[@]}" port geth 8545)
export E2E_GETH_PORT="${published##*:}"
[[ $E2E_GETH_PORT =~ ^[0-9]+$ ]] || { echo 'Invalid geth published port' >&2; exit 1; }
printf "E2E_GETH_PORT='%s'\n" "$E2E_GETH_PORT" >> "$E2E_RUN_ROOT/container.env"
"${compose[@]}" run --rm -T harness "$E2E_RUN_ROOT/bin/scope.test" \
  -test.v -test.count=1 -test.timeout="${E2E_TEST_TIMEOUT:-90m}" "$@"
